$thc_logo_base64 = 'data:image/png;base64,';
$thc_logo_src = 'global_assets/images/final_logo2.png';

if (!file_exists(__DIR__ . '/../global_assets/images/final_logo2.png')) {
    if (file_exists(__DIR__ . '/../global_assets/images/backgrounds/final_logo2.png')) {
        $thc_logo_src = 'global_assets/images/backgrounds/final_logo2.png';
    } elseif (file_exists(__DIR__ . '/../assets/images/final_logo2.png')) {
